//! Shared test fixture helpers for action contracts and capability grants.

use vb_core::action::{ActionContract, ActionName, Idempotency, RetrySafety, SideEffect};
use vb_core::capability::{Capability, CapabilitySet};
use vb_core::ids::{ActionId, RunId, SlotIdx};
use vb_core::SlotValue;

/// Create action contracts for all action IDs from 0 through the given maximum.
pub(crate) fn contracts_through(max_action: ActionId) -> Box<[ActionContract]> {
    let target = u16::from(max_action.get());
    let mut contracts = Vec::with_capacity(usize::from(target) + 1);
    let mut id = 0u16;
    loop {
        let current = ActionId::new(id);
        let name = ActionName::new("test-action").unwrap();
        contracts.push(ActionContract {
            id: current,
            name,
            input_slot_count: 1,
            output_slot_count: 1,
            max_input_bytes: 1024,
            max_output_bytes: 1024,
            timeout_ms: 5000,
            idempotency: Idempotency::DeterministicPure,
            side_effect: SideEffect::None,
            retry_safety: RetrySafety::Safe,
            required_capabilities: Box::new([Capability::new("__contract_required__".into(), current)]),
        });
        if id == target {
            break;
        }
        id = id.saturating_add(1);
    }
    contracts.into_boxed_slice()
}

/// Create a capability set that grants the contract capability for the given action.
pub(crate) fn contract_capability_for(action: ActionId) -> CapabilitySet {
    CapabilitySet::from_grants(Box::new([Capability::new("__contract_required__".into(), action)]))
}

/// Submit a suspended workflow with proper action contracts and capabilities.
/// This is the canonical way to submit workflows with Do actions in tests.
pub(crate) fn submit_suspended(
    shard: &mut super::super::types::Shard,
    run: vb_core::ids::RunId,
    workflow: vb_core::workflow::CompiledWorkflow,
) -> crate::RuntimeResult<()> {
    shard.handle_submit_with_inputs_and_contracts(
        run,
        workflow,
        &[(SlotIdx::new(0), SlotValue::I64(0))],
        contract_capability_for(ActionId::new(0)),
        &contracts_through(ActionId::new(0)),
    )
}

pub(crate) fn handle_submit_with_inputs_and_contracts(
    &mut self,
    run: RunId,
    workflow: CompiledWorkflow,
    inputs: &[(SlotIdx, SlotValue)],
    caps: CapabilitySet,
    action_contracts: &[vb_core::action::ActionContract],
) -> RuntimeResult<()> {
    self.validate_submit_admission_with_contracts(
        run,
        &workflow,
        caps.clone(),
        action_contracts,
    )?;
    self.handle_submit_with_inputs_contracts_and_header_mode(
        run,
        workflow,
        inputs,
        caps,
        action_contracts,
        true,
    )
}

fn handle_submit_with_inputs_contracts_and_header_mode(
    &mut self,
    run: RunId,
    workflow: CompiledWorkflow,
    inputs: &[(SlotIdx, SlotValue)],
    caps: CapabilitySet,
    action_contracts: &[vb_core::action::ActionContract],
    persist_header: bool,
) -> RuntimeResult<()> {
    if self.run_state_contains(run) {
        return Err(RuntimeError::RunAlreadyExists);
    }
    if self.active_run_count() >= self.max_active_runs {
        return Err(RuntimeError::ActiveRunCapacityExceeded {
            capacity: self.max_active_runs,
        });
    }
    self.prepare_run_slots(run)?;
    let digest = workflow.digest();
    let admission = self.build_admission(run, digest, caps)?;
    let mut frame = self.take_frame_for(run, &workflow)?;
    crate::shard::helpers::seed_input_slots(&mut frame, inputs, &workflow)?;
    self.trace_ring.push(TraceEvent::RunSubmitted { run });
    if persist_header {
        self.append_admission_header_journal_event(
            run,
            RuntimeJournalEvent::RunSubmitted {
                run,
                workflow: digest,
            },
        )?;
    }
    if let Some(admission) = admission.as_ref() {
        self.append_admission_header_journal_event(
            run,
            RuntimeJournalEvent::RunAdmission {
                admission: admission.clone(),
            },
        )?;
    }
    self.counters.inc_submitted();
    let frame_step_count = frame.step_count();
    let max_slots = workflow.resource_contract().max_slots;
    let state = RunState {
        frame,
        workflow,
        store: ValueStore::with_max_slots(max_slots),
        action_attempts: crate::shard::helpers::new_action_attempts(frame_step_count),
        admission,
        collect_states: CollectStates::new(),
        action_contracts: action_contracts.to_vec().into_boxed_slice(),
    };
    self.terminal_runs_remove(run);

